internal sealed class DashboardHelp:DashboardDialog {
    internal sealed class Topic {internal string Title,Body;internal Topic(string title,string body){Title=title;Body=body;}public override string ToString(){return Title;}}
    internal static readonly Topic[] Topics={
        new Topic("Getting started","Local Dashboard opens on demand. The Dashboard contains your saved software projects, website projects, development documents, everyday websites and workflows. Select a section in the sidebar. All links shows every saved destination.\r\n\r\nChoose Current work in the sidebar or View > Current work checklist for the compact checklist. Dashboard returns to the full window. Each view keeps its own size while the app is open. Windows startup is off by default. File > Settings provides optional window and startup choices."),
        new Topic("Projects, folders and websites","Folder opens the saved folder directly in Windows Explorer. Notes or Open opens the original document in its Windows app. Website opens the saved address in Firefox, or the default browser when Firefox is unavailable. Catalog opens the original searchable media-catalog HTML in the browser.\r\n\r\nOpen folder above Software projects or Website projects opens that section's main workspace. The app does not move or copy project contents. Unavailable destinations are disabled; correct the saved location before using them again."),
        new Topic("Edit sidebar and project order","Click the small Edit control below the sidebar list to unlock one shared editing draft. Drag a sidebar handle to reorder sections. Click a section name or press F2 to rename its label inline; Enter accepts the name in the draft, and Escape abandons that name edit. The section still selects its project list.\r\n\r\nWhile editing, drag handles in the project list to reorder items. Focus a section or project row and press Ctrl+Up or Ctrl+Down for keyboard reordering. Project rows have no rename control: native software/website/workspace names come from the folder paths configured in catalog.json. Nothing moves or renames a real folder.\r\n\r\nSave commits sidebar labels and item orders together and locks the controls. Cancel discards the whole draft. Closing without Save does not commit. Normal mode has no drag handles or inline renaming. If another window or manual edit changed the saved layout, Save is rejected; Cancel to reload the latest layout before editing again. Custom item order takes precedence over star sorting. Newly catalogued items append deterministically.\r\n\r\nBroadcast & Media provides direct access to Paranormal Archive and its media catalog. The PA project row includes Artwork for the original approved artwork review HTML."),
        new Topic("Human maintenance","Use Edit below the sidebar list for section labels, section order and item order. Use the checklist checkboxes for completion and restore. Project names, actual target paths, catalog membership and icons have no editor in this version.\r\n\r\nThose values come from catalog.json in the Local Dashboard folder. Projects are not automatically discovered. For software, websites and other workspaces, the native label is the final folder name from the configured Folder path; documents and workflows use the saved name field. Changing a target path changes the destination, not the actual folder name.\r\n\r\nFor exact fields, examples, safe manual edits, backup and recovery, open the maintenance guide linked below. It also links the Current Work contract, whose completion/revision rules remain authoritative. Close dashboard windows and make a backup before manually editing configuration. Do not replace a damaged file with empty defaults."),
        new Topic("Search and pinned links","Use Search all links to find a saved project, document, workflow or website. Typing switches the results to All links. Clear the search to see every destination, or select a section.\r\n\r\nThe star on a link keeps it at the top of its section when no custom item order is saved. A custom order takes precedence. Click again to remove that link pin. Link pins are separate from Always on top, which pins the app window. Refresh reloads saved navigation changes without restarting the app."),
        new Topic("Current work and Done","The Current tab lists the selected work you still want to review or finish. Check an item only when you want to mark it complete. It disappears from Current and remains in Done. Open Done and uncheck an item to restore it to Current.\r\n\r\nCheckoffs save immediately on this computer and remain after closing and reopening. Completing a checklist item is your confirmation; the app does not independently verify that the underlying work was finished. This selected checklist does not replace the Master To-Do List or project notes."),
        new Topic("Ask Quinn to update","Ask Quinn to update opens a request for review. Choose Copy request, then paste and send it in Quinn's existing chat. Nothing is sent automatically. The request identifies the saved checklist and its revision so an update can preserve your checkoffs.\r\n\r\nViewing, checking and restoring items require no AI. An update you send in chat uses normal account usage. No background model polling runs. Only verified current work should be added; past conversations are not automatically imported."),
        new Topic("Always on top, Hide and Close","Always on top in Dashboard, On top in compact view, or View > Always on top keeps this window above other windows. A checkmark shows when it is on. Choose it again to turn it off. This setting does not create a startup task.\r\n\r\nHide sends the window to the notification area. Double-click the Local Dashboard icon there, or right-click it and choose Show, to return. Opening the same launcher again also brings its window back.\r\n\r\nFile > Settings offers Close to the system tray, Minimize to the system tray, Start when I sign in to Windows and Start minimized in the system tray. All are off by default. Close follows your saved choice. File > Exit and tray > Exit always quit. Windows startup opens the executable shown in Settings; enabling it in a review build starts that review build. Saved checklist progress is retained."),
        new Topic("Participating task reports","View > Participating task reports shows explicitly supplied reports separately from the Current Work checklist. Each report identifies its source, actual project folder, state and timestamp.\r\n\r\nReports older than two minutes show Last reported and Stale / offline. A fresh report from one source does not renew another source. These reports do not represent automatic coverage of every desktop or cloud chat, and they never complete checklist items."),
        new Topic("Saved data and update conflicts","The checklist is saved in .local/current-work.json beneath the Local Dashboard folder. Current and Done are two views of the same file. Keep that file when backing up the dashboard. Navigation is stored separately in catalog.json, and link pins are separate again.\r\n\r\nIf another update saved first, an outdated edit is rejected instead of overwriting your changes. Refresh and review the latest version before trying again. Metadata updates preserve completed items; they do not silently restore them. A damaged or unsupported checklist is not replaced with an empty one."),
        new Topic("Troubleshooting","If a folder or note does not open, confirm the original destination still exists and use Refresh. A browser-only HTML fallback cannot provide the desktop app's Explorer behavior.\r\n\r\nIf Checklist unavailable appears, checkoffs are disabled until the saved file can be read safely. Existing data is left unchanged. Ask for help repairing the file rather than deleting or overwriting it.\r\n\r\nIf the window seems missing, check the notification area or reopen its launcher. If a report looks old, read its timestamp and source; stale means the app cannot claim its state is current.\r\n\r\nF1 opens this guide. Ctrl+R refreshes the directory, Ctrl+Shift+C opens Current Work, and Ctrl+Q exits.")
    };
    readonly TextBox search=new TextBox();readonly ListBox topics=new ListBox();readonly Label title=new Label();readonly Label article=new Label();readonly Panel articleHost=new Panel();bool fittingArticle;
