        var searchLabel=Label("Search help",Font,DashboardForm.Ink);Controls.Add(searchLabel);
        search.BackColor=DashboardForm.Surface;search.ForeColor=DashboardForm.Ink;search.BorderStyle=BorderStyle.FixedSingle;search.AccessibleName="Search help";Controls.Add(search);
