        title.Font=new Font("Segoe UI Variable Display",15,FontStyle.Bold);title.ForeColor=DashboardForm.Ink;title.UseMnemonic=false;Controls.Add(title);
        article.UseMnemonic=false;article.BackColor=DashboardForm.Background;article.ForeColor=DashboardForm.Ink;article.Font=Font;article.AccessibleName="Help topic text";articleHost.AutoScroll=true;articleHost.BackColor=DashboardForm.Background;articleHost.Controls.Add(article);Controls.Add(articleHost);articleHost.Resize+=(s,e)=>FitArticle();
        var close=DashboardForm.LinkButton("Close");close.DialogResult=DialogResult.Cancel;Controls.Add(close);CancelButton=close;
        var maintenance=new LinkLabel{Text="Open maintenance guide",LinkColor=DashboardForm.Accent,ActiveLinkColor=DashboardForm.Ink,VisitedLinkColor=DashboardForm.Accent,AccessibleName="Open human maintenance source guide"};maintenance.LinkClicked+=(s,e)=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppData.Root,".dev","Human Maintenance.md")){UseShellExecute=true});}catch(Exception error){MessageBox.Show(this,error.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);}};Controls.Add(maintenance);
        topics.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var fill=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(56,56,56):DashboardForm.Surface))e.Graphics.FillRectangle(fill,e.Bounds);TextRenderer.DrawText(e.Graphics,topics.Items[e.Index].ToString(),Font,Rectangle.Inflate(e.Bounds,-10,0),DashboardForm.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();};
        topics.SelectedIndexChanged+=(s,e)=>{var topic=topics.SelectedItem as Topic;if(topic!=null){title.Text=topic.Title;article.Text=topic.Body;articleHost.AutoScrollPosition=Point.Empty;FitArticle();}};
        search.TextChanged+=(s,e)=>Filter();Action layout=()=>{int nav=240,left=28;heading.SetBounds(left,20,ClientSize.Width-56,40);subtitle.SetBounds(left+2,65,ClientSize.Width-60,28);searchLabel.SetBounds(left,112,nav,22);search.SetBounds(left,140,nav,26);topics.SetBounds(left,182,nav,Math.Max(40,ClientSize.Height-270));maintenance.SetBounds(left,ClientSize.Height-58,nav,38);title.SetBounds(left+nav+28,112,Math.Max(80,ClientSize.Width-nav-84),38);articleHost.SetBounds(left+nav+28,162,Math.Max(80,ClientSize.Width-nav-84),Math.Max(40,ClientSize.Height-240));FitArticle();close.SetBounds(ClientSize.Width-138,ClientSize.Height-58,110,38);};Resize+=(s,e)=>layout();layout();Filter();
    }
    void FitArticle(){if(fittingArticle)return;fittingArticle=true;try{int width=Math.Max(80,articleHost.ClientSize.Width-16);article.Width=width;article.Height=TextRenderer.MeasureText(article.Text,article.Font,new Size(width,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl).Height+8;articleHost.AutoScrollMinSize=new Size(0,article.Height);}finally{fittingArticle=false;}}
    void Filter(){topics.BeginUpdate();topics.Items.Clear();string query=search.Text.Trim();foreach(var topic in Topics.Where(t=>(t.Title+" "+t.Body).IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0))topics.Items.Add(topic);topics.EndUpdate();if(topics.Items.Count>0)topics.SelectedIndex=0;else{title.Text="No matching topics";article.Text="Try a word such as folder, Done, Hide or saved data.";FitArticle();}}
    internal void Verify(){search.Text="checkoffs";if(topics.Items.Count==0)throw new Exception("Guide search found no expected topic.");search.Text="no-such-help-topic-914827";if(topics.Items.Count!=0||title.Text!="No matching topics")throw new Exception("Guide empty search failed.");search.Text="";if(topics.Items.Count!=Topics.Length)throw new Exception("Guide reset failed.");}
    protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(keyData==(Keys.Control|Keys.F)){search.Focus();return true;}return base.ProcessCmdKey(ref message,keyData);}
